{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */

import { stdin as input } from 'process'
import { createInterface } from 'readline'

import { Sheet } from './sheet.js'

const mode = process.argv[2]

if (mode !== 'values' && mode !== 'deps') {
  process.stderr.write('error: usage: cli.js values|deps\n')
  process.exit(2)
}

let inputData = ''

const rl = createInterface({
  input,
  crlfDelay: Infinity
})

rl.on('line', (line) => {
  inputData += line + '\n'
})

rl.on('close', () => {
  try {
    const sheet = new Sheet(inputData)
    const output = mode === 'values' ? sheet.outputValues() : sheet.outputDeps()
    process.stdout.write(output)
    process.exit(0)
  } catch (err) {
    process.stderr.write(err.message + '\n')
    process.exit(2)
  }
})
"}

