{"file_path":"src/sheet.js","content":"import { parseAddress, formatAddress } from './address.js'
import { Parser } from './parser.js'
import { evaluateFormula } from './evaluator.js'

export class Sheet {
  constructor(input) {
    this.cells = new Map() // Map<addressStr, { address, content, isFormula }>
    this.values = new Map() // Map<addressStr, value>
    this.dependencies = new Map() // Map<addressStr, Set<addressStr>>
    this.evaluating = new Set() // For cycle detection

    this.parseInput(input)
  }

  parseInput(input) {
    const lines = input.split('\n')

    for (let lineNum = 0; lineNum < lines.length; lineNum++) {
      let line = lines[lineNum]

      // Strip leading spaces and tabs
      const trimmed = line.replace(/^[ \t]+/, '')

      // Ignore empty lines or comments
      if (!trimmed || trimmed.startsWith('#')) {
        continue
      }

      // Parse address and content
      const match = trimmed.match(/^(\S+)[ \t]+(.*)$/)
      if (!match) {
        continue // This shouldn't happen given valid input, but be safe
      }

      const addressStr = match[1]
      const content = match[2]

      // Parse and validate address
      let address
      try {
        address = parseAddress(addressStr)
      } catch (e) {
        throw new Error(`error: line ${lineNum + 1}: invalid cell address ${addressStr}`)
      }

      const key = formatAddress(address)

      // Check for duplicates
      if (this.cells.has(key)) {
        throw new Error(`error: line ${lineNum + 1}: cell ${key} is declared twice`)
      }

      const isFormula = content.startsWith('=')
      this.cells.set(key, {
        address,
        content: isFormula ? content.slice(1) : content,
        isFormula
      })
    }
  }

  getCellValue(address, evaluating = new Set()) {
    const key = formatAddress(address)

    // Check for cycles
    if (evaluating.has(key)) {
      return { type: 'error', value: '#CYCLE!' }
    }

    // Return cached value if available
    if (this.values.has(key)) {
      return this.values.get(key)
    }

    const cell = this.cells.get(key)
    let value

    if (!cell) {
      // Undeclared cell is 0
      value = { type: 'number', value: 0 }
    } else if (cell.isFormula) {
      // Evaluate formula
      const newEvaluating = new Set(evaluating)
      newEvaluating.add(key)

      try {
        value = evaluateFormula(cell.content, this, newEvaluating)
      } catch (e) {
        value = { type: 'error', value: '#ERR!' }
      }
    } else {
      // Parse literal
      value = parseLiteral(cell.content)
    }

    this.values.set(key, value)
    return value
  }

  getCellDependencies(address) {
    const key = formatAddress(address)

    if (this.dependencies.has(key)) {
      return this.dependencies.get(key)
    }

    const cell = this.cells.get(key)
    const deps = new Set()

    if (cell && cell.isFormula) {
      try {
        const parser = new Parser(cell.content)
        const ast = parser.parseExpression()
        collectDependencies(ast, deps)
      } catch (e) {
        // Grammar error: no dependencies
      }
    }

    this.dependencies.set(key, deps)
    return deps
  }

  outputValues() {
    const lines = []
    const sorted = Array.from(this.cells.keys()).sort(compareAddresses)

    for (const key of sorted) {
      const cell = this.cells.get(key)
      const value = this.getCellValue(cell.address)
      lines.push(`${key}=${formatValue(value)}`)
    }

    return lines.length > 0 ? lines.join('\n') + '\n' : ''
  }

  outputDeps() {
    const lines = []
    const sorted = Array.from(this.cells.keys()).sort(compareAddresses)

    for (const key of sorted) {
      const cell = this.cells.get(key)
      const deps = this.getCellDependencies(cell.address)

      const depArray = Array.from(deps).sort(compareAddresses)
      const depStr = depArray.length > 0 ? ' ' + depArray.join(' ') : ''
      lines.push(`${key}:${depStr}`)
    }

    return lines.length > 0 ? lines.join('\n') + '\n' : ''
  }
}

function parseLiteral(content) {
  if (!content) {
    return { type: 'number', value: 0 }
  }

  // Check for error tokens
  const errorTokens = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']
  if (errorTokens.includes(content)) {
    return { type: 'error', value: content }
  }

  // Try to parse as number
  if (/^-?\d+(?:\.\d+)?$/.test(content)) {
    return { type: 'number', value: parseFloat(content) }
  }

  // Otherwise it's text
  return { type: 'text', value: content }
}

function formatValue(value) {
  if (value.type === 'error') {
    return value.value
  } else if (value.type === 'boolean') {
    return value.value ? 'TRUE' : 'FALSE'
  } else if (value.type === 'number') {
    // Round to 10 significant digits
    const rounded = parseFloat(value.value.toPrecision(10))
    // Format as JavaScript would
    return String(rounded)
  } else {
    return value.value
  }
}

function compareAddresses(a, b) {
  const addrA = parseAddress(a)
  const addrB = parseAddress(b)

  if (addrA.col !== addrB.col) {
    return addrA.col - addrB.col
  }
  return addrA.row - addrB.row
}

function collectDependencies(ast, deps) {
  if (!ast) return

  if (ast.type === 'address') {
    deps.add(formatAddress(ast.value))
  } else if (ast.type === 'range') {
    // Add all cells in range
    const { start, end } = ast.value
    for (let col = Math.min(start.col, end.col); col <= Math.max(start.col, end.col); col++) {
      for (let row = Math.min(start.row, end.row); row <= Math.max(start.row, end.row); row++) {
        deps.add(formatAddress({ col, row }))
      }
    }
  } else if (ast.type === 'binary') {
    collectDependencies(ast.left, deps)
    collectDependencies(ast.right, deps)
  } else if (ast.type === 'unary') {
    collectDependencies(ast.operand, deps)
  } else if (ast.type === 'call') {
    for (const arg of ast.args) {
      collectDependencies(arg, deps)
    }
  }
}
"}

