{"file_path":"src/address.js","content":"/**
 * Parse a cell address string like "A1" or "AA99" into {col, row}
 * Columns are 0-indexed (A=0, Z=25, AA=26, etc.)
 * Rows are 1-indexed
 */
export function parseAddress(addressStr) {
  const upper = addressStr.toUpperCase()

  // Match pattern: 1-2 letters followed by 1-3 digits
  const match = upper.match(/^([A-Z]{1,2})(\d{1,3})$/)

  if (!match) {
    throw new Error(`Invalid address: ${addressStr}`)
  }

  const colStr = match[1]
  const rowStr = match[2]

  // Parse column (A=0, Z=25, AA=26, ZZ=701)
  let col = 0
  for (let i = 0; i < colStr.length; i++) {
    col = col * 26 + (colStr.charCodeAt(i) - 'A'.charCodeAt(0) + 1)
  }
  col-- // Convert to 0-indexed

  // Validate column range (A-Z = 0-25, AA-ZZ = 26-701)
  if (col < 0 || col > 701) {
    throw new Error(`Invalid address: ${addressStr}`)
  }

  const row = parseInt(rowStr, 10)

  // Validate row range (1-999)
  if (row < 1 || row > 999) {
    throw new Error(`Invalid address: ${addressStr}`)
  }

  return { col, row }
}

/**
 * Convert {col, row} back to address string
 */
export function formatAddress({ col, row }) {
  // Convert 0-indexed column to letters
  let colStr = ''
  let c = col + 1 // Convert to 1-indexed
  while (c > 0) {
    c-- // Adjust for 0-based modulo
    colStr = String.fromCharCode('A'.charCodeAt(0) + (c % 26)) + colStr
    c = Math.floor(c / 26)
  }

  return colStr + row
}

/**
 * Check if a string is a valid cell address
 */
export function isValidAddress(addressStr) {
  try {
    parseAddress(addressStr)
    return true
  } catch {
    return false
  }
}
"}

