{"file_path":"src/parser.js","content":"import { parseAddress, isValidAddress } from './address.js'

export class Parser {
  constructor(formulaText) {
    this.text = formulaText
    this.pos = 0
  }

  parseExpression() {
    return this.parseComparison()
  }

  // Comparisons: =, <>, <, <=, >, >=
  parseComparison() {
    let left = this.parseAdditive()

    while (true) {
      this.skipWhitespace()
      const op = this.tryParseOperator(['=', '<>', '<=', '>=', '<', '>'])
      if (!op) break

      this.skipWhitespace()
      const right = this.parseAdditive()
      left = {
        type: 'binary',
        op,
        left,
        right
      }
    }

    return left
  }

  // Addition and subtraction
  parseAdditive() {
    let left = this.parseMultiplicative()

    while (true) {
      this.skipWhitespace()
      const op = this.tryParseOperator(['+', '-'])
      if (!op) break

      this.skipWhitespace()
      const right = this.parseMultiplicative()
      left = {
        type: 'binary',
        op,
        left,
        right
      }
    }

    return left
  }

  // Multiplication and division
  parseMultiplicative() {
    let left = this.parseExponentiation()

    while (true) {
      this.skipWhitespace()
      const op = this.tryParseOperator(['*', '/'])
      if (!op) break

      this.skipWhitespace()
      const right = this.parseExponentiation()
      left = {
        type: 'binary',
        op,
        left,
        right
      }
    }

    return left
  }

  // Exponentiation (right associative)
  parseExponentiation() {
    let left = this.parseUnary()

    this.skipWhitespace()
    const op = this.tryParseOperator(['^'])
    if (op) {
      this.skipWhitespace()
      const right = this.parseExponentiation() // Right associative
      left = {
        type: 'binary',
        op,
        left,
        right
      }
    }

    return left
  }

  // Unary + and -
  parseUnary() {
    this.skipWhitespace()

    const op = this.tryParseOperator(['+', '-'])
    if (op) {
      this.skipWhitespace()
      const operand = this.parseUnary() // Right associative
      return {
        type: 'unary',
        op,
        operand
      }
    }

    return this.parsePrimary()
  }

  // Primary: number, address, range, call, parentheses, TRUE, FALSE
  parsePrimary() {
    this.skipWhitespace()

    // Number
    if (this.peekChar() && /\d/.test(this.peekChar())) {
      return this.parseNumber()
    }

    // Parentheses
    if (this.peekChar() === '(') {
      this.pos++
      this.skipWhitespace()
      const expr = this.parseExpression()
      this.skipWhitespace()
      if (this.peekChar() !== ')') {
        throw new Error('Expected )')
      }
      this.pos++
      return expr
    }

    // Word (TRUE, FALSE, function call, or address)
    if (this.peekChar() && /[A-Za-z]/.test(this.peekChar())) {
      const start = this.pos
      const word = this.parseWord()

      if (word === 'TRUE') {
        return { type: 'boolean', value: true }
      }
      if (word === 'FALSE') {
        return { type: 'boolean', value: false }
      }

      // Check if this is a function call
      this.skipWhitespace()
      if (this.peekChar() === '(') {
        return this.parseFunctionCall(word)
      }

      // Check if it's an address or range
      if (isValidAddress(word)) {
        const address = parseAddress(word)

        // Check for range
        this.skipWhitespace()
        if (this.peekChar() === ':') {
          this.pos++
          this.skipWhitespace()

          // Parse end address
          if (this.peekChar() && /[A-Za-z]/.test(this.peekChar())) {
            const endWord = this.parseWord()
            if (!isValidAddress(endWord)) {
              throw new Error('Invalid address in range')
            }
            const endAddress = parseAddress(endWord)
            return {
              type: 'range',
              value: { start: address, end: endAddress }
            }
          }
          throw new Error('Invalid range')
        }

        return {
          type: 'address',
          value: address
        }
      }

      // Word is not TRUE, FALSE, function, or valid address
      // It could be an invalid address or unknown function
      // For now, treat as #NAME? error or invalid address
      if (/^\d/.test(word) || word.length > 2 || (word.length === 2 && word.charCodeAt(0) < 'A'.charCodeAt(0) || word.charCodeAt(0) > 'Z'.charCodeAt(0))) {
        // Invalid address
        throw new Error('Invalid address')
      }

      throw new Error('Unknown identifier')
    }

    throw new Error('Unexpected token')
  }

  parseFunctionCall(name) {
    this.skipWhitespace()
    if (this.peekChar() !== '(') {
      throw new Error('Expected (')
    }
    this.pos++

    const args = []
    this.skipWhitespace()

    if (this.peekChar() !== ')') {
      args.push(this.parseArgument())

      while (true) {
        this.skipWhitespace()
        if (this.peekChar() !== ',') break
        this.pos++
        this.skipWhitespace()
        args.push(this.parseArgument())
      }
    }

    this.skipWhitespace()
    if (this.peekChar() !== ')') {
      throw new Error('Expected )')
    }
    this.pos++

    return {
      type: 'call',
      name: name.toUpperCase(),
      args
    }
  }

  parseArgument() {
    // An argument can be a range or an expression
    const start = this.pos
    const expr = this.parseExpression()

    // Check if this is a range that should be treated as such
    if (expr.type === 'address') {
      this.skipWhitespace()
      if (this.peekChar() === ':') {
        this.pos++
        this.skipWhitespace()

        if (this.peekChar() && /[A-Za-z]/.test(this.peekChar())) {
          const endWord = this.parseWord()
          if (!isValidAddress(endWord)) {
            throw new Error('Invalid address in range')
          }
          const endAddress = parseAddress(endWord)
          return {
            type: 'range',
            value: { start: expr.value, end: endAddress }
          }
        }
      }
    }

    return expr
  }

  parseNumber() {
    const start = this.pos

    while (this.pos < this.text.length && /[\d.]/.test(this.text[this.pos])) {
      this.pos++
    }

    const numStr = this.text.substring(start, this.pos)
    const num = parseFloat(numStr)

    return {
      type: 'number',
      value: num
    }
  }

  parseWord() {
    const start = this.pos

    while (this.pos < this.text.length && /[A-Za-z0-9]/.test(this.text[this.pos])) {
      this.pos++
    }

    return this.text.substring(start, this.pos)
  }

  tryParseOperator(ops) {
    this.skipWhitespace()

    for (const op of ops) {
      if (this.text.substring(this.pos, this.pos + op.length) === op) {
        this.pos += op.length
        return op
      }
    }

    return null
  }

  skipWhitespace() {
    while (this.pos < this.text.length && /[ \t]/.test(this.text[this.pos])) {
      this.pos++
    }
  }

  peekChar() {
    return this.pos < this.text.length ? this.text[this.pos] : null
  }
}
"}

